Here's how to write modern MSTest tests for `DataFetcher` covering async patterns, timeouts, and cancellation:

```csharp
[TestClass]
public sealed class DataFetcherTests
{
    private readonly TestContext _testContext;
    private readonly MockHttpMessageHandler _handler;
    private readonly DataFetcher _fetcher;

    public DataFetcherTests(TestContext testContext)
    {
        _testContext = testContext;
        _handler = new MockHttpMessageHandler();
        _fetcher = new DataFetcher(new HttpClient(_handler));
    }

    [TestMethod]
    public async Task FetchAsync_SuccessResponse_ReturnsContent()
    {
        _handler.ResponseContent = "hello world";
        _handler.StatusCode = HttpStatusCode.OK;

        var result = await _fetcher.FetchAsync(
            "https://example.com/data",
            _testContext.CancellationToken);

        Assert.AreEqual("hello world", result);
    }

    [TestMethod]
    public async Task FetchAsync_NotFound_ThrowsHttpRequestException()
    {
        _handler.StatusCode = HttpStatusCode.NotFound;

        await Assert.ThrowsExactlyAsync<HttpRequestException>(
            async () => await _fetcher.FetchAsync(
                "https://example.com/missing",
                _testContext.CancellationToken));
    }

    [TestMethod]
    [Timeout(5000)] // guards against hangs
    public async Task FetchAsync_CancellationRequested_ThrowsOperationCanceled()
    {
        _handler.SimulateDelay = TimeSpan.FromSeconds(30);
        using var cts = new CancellationTokenSource();
        cts.Cancel(); // cancel immediately

        await Assert.ThrowsExactlyAsync<TaskCanceledException>(
            async () => await _fetcher.FetchAsync(
                "https://example.com/slow", cts.Token));
    }

    [TestMethod]
    [Timeout(3000)]
    public async Task FetchAsync_CompletesWithinTimeout()
    {
        _handler.ResponseContent = "fast";
        _handler.StatusCode = HttpStatusCode.OK;

        // Flow TestContext.CancellationToken so [Timeout] is cooperative
        var result = await _fetcher.FetchAsync(
            "https://example.com/data",
            _testContext.CancellationToken);

        Assert.IsNotNull(result);
    }
}
```

And the test double for `HttpMessageHandler`:

```csharp
internal sealed class MockHttpMessageHandler : HttpMessageHandler
{
    public HttpStatusCode StatusCode { get; set; } = HttpStatusCode.OK;
    public string ResponseContent { get; set; } = string.Empty;
    public TimeSpan SimulateDelay { get; set; } = TimeSpan.Zero;

    protected override async Task<HttpResponseMessage> SendAsync(
        HttpRequestMessage request, CancellationToken cancellationToken)
    {
        if (SimulateDelay > TimeSpan.Zero)
            await Task.Delay(SimulateDelay, cancellationToken);

        return new HttpResponseMessage(StatusCode)
        {
            Content = new StringContent(ResponseContent)
        };
    }
}
```

**Key patterns demonstrated:**

| Pattern | How |
|---|---|
| **Async tests** | Return `async Task`, use `await` — never `async void` |
| **Cooperative timeout** | `[Timeout(ms)]` + flow `_testContext.CancellationToken` into the call under test |
| **Cancellation testing** | Create a pre-cancelled `CancellationTokenSource`, assert `TaskCanceledException` |
| **Exception testing** | `Assert.ThrowsExactlyAsync<T>` instead of `[ExpectedException]` |
| **Constructor injection** | `TestContext` injected via constructor (MSTest 3.6+), enables `readonly` fields |
| **HttpClient testing** | Subclass `HttpMessageHandler` — no need for external mocking libraries |

The critical detail: always pass `TestContext.CancellationToken` to your async calls so that `[Timeout]` can actually cancel the test cooperatively rather than letting it hang.
